import test from 'node:test';import assert from 'node:assert/strict';
import {aquaticHabitats,aquaticLife,aquaticSamples,aquaticObjects,defaultAquatic,normalizeAquatic,aquaticAction,aquaticView,aquaticVisible,aquaticArtKeys,aquaticArt,oceanWorldPresets} from '../src/aquatic.js';
import {pathfind,cellAt,blocked} from '../src/navigation.js';import {zones,zoneExit} from '../src/zones.js';import {objects,materials} from '../src/data.js';import {getJournalEntries} from '../src/journal.js';
test('lake portal and all swim/sub approaches are reachable, with habitat-specific wildlife',()=>{assert.equal(zoneExit('grounds','aquatic'),'grounds-aquatic');assert.equal(zoneExit('aquatic','grounds'),'aqua-exit');const entry=objects.find(o=>o.id==='grounds-aquatic');assert.ok(pathfind(zones.grounds.spawn,[entry.x-65,entry.y+55]).length);for(const habitat of Object.keys(aquaticHabitats)){const points=[zones.aquatic.spawn,...aquaticObjects.filter(o=>aquaticVisible({habitat},o)).map(o=>[o.x-65,o.y+55])];for(const a of points)for(const b of points){const p=pathfind(a,b,'aquatic');if(cellAt(...a).join()!==cellAt(...b).join())assert.ok(p.length,`${a} to ${b}`);for(const xy of p)assert.equal(blocked(...cellAt(...xy),'aquatic'),false)}}assert.equal(aquaticVisible({habitat:'lake'},aquaticObjects.find(o=>o.life==='whale')),false)});
test('observations, samples and completed models are repeatable and saved without consuming kits',()=>{let s=defaultAquatic();for(const a of aquaticLife)for(let i=0;i<2;i++)s=aquaticAction(s,{type:'observe',value:a.id}).aquatic;for(const a of aquaticSamples)for(let i=0;i<2;i++)s=aquaticAction(s,{type:'sample',value:a.id}).aquatic;for(const [key,n]of [['pressure',5],['depth',4],['ballast',2],['volcano',3]])for(let i=0;i<n;i++)s=aquaticAction(s,{type:'step',key}).aquatic;s=aquaticAction(s,{type:'salinity'}).aquatic;s=aquaticAction(s,{type:'ping'}).aquatic;assert.equal(s.observed.length,10);assert.equal(s.samples.length,5);assert.equal(s.completed.length,6);assert.equal(aquaticAction(s,{type:'fit',value:'printed-kit'}).aquatic.modules.length,0);const kits=['printed-kit'];s=aquaticAction(s,{type:'fit',value:kits[0]},kits).aquatic;assert.deepEqual(kits,['printed-kit']);assert.deepEqual(s.modules,kits);assert.equal(s.completed.length,7);assert.equal(normalizeAquatic({observed:['whale','bad','whale'],pressure:Infinity}).pressure,0);assert.deepEqual(normalizeAquatic({observed:['whale','bad','whale']}).observed,['whale']);for(const section of ['found','experiments']){const e=getJournalEntries(section,new Set(),new Set(),objects,materials,{}, {},s);assert.ok(e.length);assert.ok(e.every(e=>objects.some(o=>o.id===e.target)))}assert.equal(getJournalEntries('minerals',new Set(),new Set(),objects,materials,{}, {},s).length,0)});
test('every aquatic page fits native choices, has an illustration and preserves science distinctions',()=>{const kits=['beam-kit','foundation-kit','tower-kit','pipe-kit','valve-kit','power-kit','printed-kit','lift-kit','robot-kit'];const s={...defaultAquatic(),observed:aquaticLife.map(a=>a.id),samples:aquaticSamples.map(a=>a.id)},seen=new Set(),queue=['center','samples','cleanup',...aquaticLife.map(a=>'life:'+a.id)];while(queue.length){const route=queue.shift();if(seen.has(route))continue;seen.add(route);const v=aquaticView(s,route,kits);assert.ok(v.actions.length<=6,route);assert.ok(aquaticArtKeys.includes(v.art),route+' '+v.art);assert.ok(aquaticArt(v.art).startsWith('<svg'));for(const a of v.actions)if(a.type==='page')queue.push(a.route)}for(const route of ['enceladus','pressure','depth','buoyancy','volcano','salinity','sonar','gigantism','reef','habitat','kits:6'])assert.ok(seen.has(route),route);for(let i=0;i<6;i++)assert.ok(aquaticView({...s,pressure:i},'pressure').text.includes('atmospheres'));assert.match(aquaticView(s,'enceladus').text,/No life has been confirmed/);assert.equal(oceanWorldPresets.enceladus.parent,'Saturn');assert.equal(oceanWorldPresets.enceladus.iceCovered,true)});
